-- Accounts (wallets) owned by customers. One customer has many accounts;
-- at most one ACTIVE account per currency.
--
-- Money: numeric(19,2), never float. Balance can never go negative (checked here AND in the
-- domain). Concurrent updates are serialised with optimistic locking on "version".
--
-- Ids are UUIDs generated by the application (Account.open), so no sequence is needed.
-- currency is VARCHAR(3), not CHAR(3): Hibernate's ddl-auto=validate maps String to varchar.
-- demo_app gets SELECT/INSERT/UPDATE/DELETE automatically through the default privileges
-- created in docker/postgres/init/01-roles.sh.

CREATE TABLE account (
                         id          UUID          NOT NULL,
                         customer_id UUID          NOT NULL,
                         currency    VARCHAR(3)    NOT NULL,
                         balance     NUMERIC(19,2) NOT NULL DEFAULT 0,
                         status      VARCHAR(16)   NOT NULL,
                         version     BIGINT        NOT NULL,
                         created_at  TIMESTAMPTZ   NOT NULL DEFAULT now(),
                         CONSTRAINT pk_account PRIMARY KEY (id),
    -- RESTRICT: a customer that still has accounts cannot be deleted
                         CONSTRAINT fk_account_customer FOREIGN KEY (customer_id)
                             REFERENCES customer (id) ON DELETE RESTRICT,
                         CONSTRAINT ck_account_balance_not_negative CHECK (balance >= 0),
                         CONSTRAINT ck_account_status CHECK (status IN ('ACTIVE', 'CLOSED')),
                         CONSTRAINT ck_account_currency_iso CHECK (currency ~ '^[A-Z]{3}$')
    );

-- "Accounts of a customer" lookups, and the FK check when a customer is deleted
CREATE INDEX ix_account_customer_id ON account (customer_id);

-- Business rule: one ACTIVE account per customer and currency. Closed accounts are kept as history.
-- The application translates a violation into 409 ACCOUNT_ALREADY_EXISTS.
CREATE UNIQUE INDEX uq_account_customer_currency_active
    ON account (customer_id, currency)
    WHERE status = 'ACTIVE';
